  blob.rotation.x = -Math.PI / 2;
  blob.position.y = 0.03;
  blob.scale.set(1.15, 1.6, 1);
  root.add(blob);

  const nose = new THREE.Object3D();
  nose.position.set(0, top, -1.55);
  const tailMark = new THREE.Object3D();
  tailMark.position.set(0, top, 1.35);
  root.add(nose, tailMark);

  const footGeo = footGeometry();
  const feet = [
    { x: -0.12, z: -0.02 },
    { x: 0.13, z: 0.22 },
  ];
  for (const f of feet) {
    const foot = new THREE.Mesh(footGeo, feetMat);
    foot.position.set(f.x, top + 0.01, f.z);
    root.add(foot);
  }

  const pivot = new THREE.Group();
  pivot.position.set(0, 0.42, 0.08);
  root.add(pivot);

  // Body parts are parented to root first (identity), then attached to pivot
  // so banking rotates them around the hips and the feet stay on the deck.
  const bodyParts = [];
  const body = mesh(root, new THREE.SphereGeometry(0.4, 28, 20), plumage, 0, 0.7, 0.1);
  body.scale.set(0.78, 0.66, 1.22);
  bodyParts.push(body);

  const belly = mesh(root, new THREE.SphereGeometry(0.28, 20, 16), bellyMat, 0, 0.58, -0.22);
  belly.scale.set(0.85, 0.72, 0.85);
  bodyParts.push(belly);

  const curve = new THREE.CatmullRomCurve3([
    new THREE.Vector3(0, 0.82, -0.12),
    new THREE.Vector3(0, 1.02, -0.22),
    new THREE.Vector3(0, 1.2, -0.46),
    new THREE.Vector3(0, 1.24, -0.66),
  ]);
  const neck = new THREE.Mesh(new THREE.TubeGeometry(curve, 18, 0.1, 10, false), neckMat);
  root.add(neck);
  bodyParts.push(neck);

  for (const spread of [-0.22, 0, 0.22]) {
    const feather = mesh(root, new THREE.BoxGeometry(0.14, 0.018, 0.42), plumage, 0, 0.74, 0.62);
    feather.rotation.y = spread;
    feather.rotation.x = 0.35;
    bodyParts.push(feather);
  }

  const head = new THREE.Group();
  head.position.set(0, 1.26, -0.74);
  const skull = mesh(head, new THREE.SphereGeometry(0.2, 22, 16), headMat, 0, 0, 0);
  skull.scale.set(1, 0.92, 1.08);
  const cap = mesh(head, new THREE.SphereGeometry(0.19, 16, 12), napeMat, 0, 0.05, 0.06);
  cap.scale.set(0.92, 0.62, 0.78);

  const upper = mesh(head, new THREE.CylinderGeometry(0.026, 0.058, 0.92, 14), beakMat, 0, -0.02, -0.5);
  upper.rotation.x = -Math.PI / 2 - 0.2;
  const lower = mesh(
    head,
    new THREE.CylinderGeometry(0.018, 0.042, 0.72, 12),
    beakLowMat,
    0,
    -0.09,
    -0.42,
  );
  lower.rotation.x = -Math.PI / 2 - 0.42;

  const pouch = mesh(head, new THREE.SphereGeometry(0.18, 20, 14), pouchMat, 0, -0.14, -0.4);
  pouch.scale.set(0.7, 0.9, 1.2);

  const hook = mesh(head, new THREE.ConeGeometry(0.03, 0.12, 8), hookMat, 0, -0.1, -0.96);
  hook.rotation.x = Math.PI;
  const knob = mesh(head, new THREE.SphereGeometry(0.042, 10, 8), knobMat, 0, 0.045, -0.78);
  knob.scale.set(0.75, 1.15, 1.25);

  const eyeL = makeEye(head, -0.095);
  const eyeR = makeEye(head, 0.095);
  const beakTip = new THREE.Object3D();
  beakTip.position.set(0, -0.12, -1.02);
  head.add(beakTip);

  root.add(head);
  bodyParts.push(head);

  const wingR = makeWing(1);
  const wingL = makeWing(-1);
  root.add(wingR, wingL);
  bodyParts.push(wingR, wingL);

  for (const part of bodyParts) pivot.attach(part);

  // Short dark legs from the deck up into the body, left on the root so they
  // stay planted when the torso banks.
  limb(root, new THREE.Vector3(-0.12, top + 0.02, -0.02), new THREE.Vector3(-0.1, 0.4, -0.02), 0.035, feetMat);
  limb(root, new THREE.Vector3(0.13, top + 0.02, 0.22), new THREE.Vector3(0.1, 0.4, 0.12), 0.035, feetMat);

  return {
    root,
    pivot,
    wingL,
    wingR,
    head,
    pouch,
    eyeL,
    eyeR,
    nose,
    tailMark,
    beakTip,
    stringer,
  };
}

export function posePelican(rig, t, ride) {
  rig.pivot.rotation.order = "YXZ";
  rig.pivot.rotation.x = ride.pitch;
  rig.pivot.rotation.z = ride.bank;
  rig.pivot.rotation.y = ride.bank * -0.35;

  const flap =
    Math.sin(t * 1.3) * 0.04 +
    Math.max(0, Math.sin(t * 0.55)) ** 8 * Math.sin(t * 9.0) * 0.28;
  const open = 0.12 * ride.lip;
  // rotation.z * side lifts both tips; bank raises the trough-side wing (+x, side 1).
  rig.wingR.rotation.set(0.12, -0.55, 0.48 + flap + open + ride.bank * 0.45);
  rig.wingL.rotation.set(0.12, 0.55, -0.48 - flap - open + ride.bank * 0.2);

  rig.head.rotation.x = -0.06 + Math.sin(t * 1.6) * 0.035 - ride.pitch * 0.25;
  rig.head.rotation.z = -ride.bank * 0.3;
  rig.head.rotation.y = Math.sin(t * 0.8) * 0.04;

  const py = 0.9 + Math.sin(t * 2.1) * 0.035;
  rig.pouch.scale.set(0.7, py, 1.2);

  const blink = Math.max(0, Math.sin(t * 0.47)) ** 48;
  const sy = 1 - blink * 0.92;
  rig.eyeL.ball.scale.y = sy;
  rig.eyeR.ball.scale.y = sy;
}

function softDisc() {
  const c = document.createElement("canvas");
  c.width = 64;
  c.height = 64;
  const g = c.getContext("2d");
  const grd = g.createRadialGradient(32, 32, 4, 32, 32, 32);
  grd.addColorStop(0, "rgba(255,255,255,0.85)");
  grd.addColorStop(1, "rgba(255,255,255,0)");
  g.fillStyle = grd;
  g.fillRect(0, 0, 64, 64);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

export function sprayTexture() {
  const c = document.createElement("canvas");
  c.width = 64;
  c.height = 64;
  const g = c.getContext("2d");
  const grd = g.createRadialGradient(32, 32, 1, 32, 32, 30);
  grd.addColorStop(0, "rgba(255,255,255,0.95)");
  grd.addColorStop(0.45, "rgba(255,255,255,0.35)");
  grd.addColorStop(1, "rgba(255,255,255,0)");
  g.fillStyle = grd;
  g.fillRect(0, 0, 64, 64);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

import * as THREE from "three";
import { heightAt, createWater, createSky, TRAIL_N, HORIZON } from "./ocean.js";
import { createRideState, sampleRide, alignToSurface, flatRight } from "./ride.js";
import { createPelican, posePelican, sprayTexture } from "./pelican.js";

const SUN = new THREE.Vector3(0.32, 0.52, 0.62).normalize();

const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: false });
renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.05;
renderer.setClearColor(HORIZON, 1);
document.body.appendChild(renderer.domElement);

const scene = new THREE.Scene();
const camera = new THREE.PerspectiveCamera(
  38,
  window.innerWidth / Math.max(1, window.innerHeight),
  0.12,
  600,
);

scene.add(new THREE.AmbientLight(0xffe2cc, 0.22));
const hemi = new THREE.HemisphereLight(0xffc9a0, 0x16485a, 0.95);
scene.add(hemi);
const sun = new THREE.DirectionalLight(0xfff1d4, 2.15);
sun.target.position.set(0, 0, 0);
scene.add(sun, sun.target);
const fill = new THREE.DirectionalLight(0x9ec8ea, 0.45);
scene.add(fill);

const sky = createSky();
scene.add(sky);
sky.material.uniforms.uSunDir.value.copy(SUN);

const water = createWater();
scene.add(water.mesh);
water.uniforms.uSunDir.value.copy(SUN);

const rig = createPelican();
scene.add(rig.root);

const flock = createFlock();
scene.add(flock.group);
const clouds = createClouds();
scene.add(clouds);

const spray = createSpray();
scene.add(spray.points);

const ride = createRideState();
const right = new THREE.Vector3();
const look = new THREE.Vector3();
const lookSmooth = new THREE.Vector3();
const camDesired = new THREE.Vector3();
const focus = new THREE.Vector3();
const tailWorld = new THREE.Vector3();
const emitA = new THREE.Vector3();
const emitB = new THREE.Vector3();
const sunPos = new THREE.Vector3();
const fillPos = new THREE.Vector3();

const trail = water.uniforms.uTrail.value;
let trailWarm = false;
let lastTrail = new THREE.Vector2(1e4, 1e4);
let ready = false;

const clock = new THREE.Clock();

window.addEventListener("resize", () => {
  camera.aspect = window.innerWidth / Math.max(1, window.innerHeight);
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
});

function frame(t, dt) {
  sampleRide(t, ride);
  alignToSurface(rig.root, ride.normal, ride.travel);
  rig.root.position.copy(ride.position);
  posePelican(rig, t, ride);

  flatRight(ride.travel, right);
  const fwd = ride.travel;

  focus.copy(ride.position).addScaledVector(ride.normal, 0.85);
  // Ahead of the beak and toward the trough, so the wave face sits behind the bird.
  camDesired
    .copy(focus)
    .addScaledVector(fwd, 6.2)
    .addScaledVector(right, 4.4)
    .addScaledVector(ride.normal, 1.55);
  const camH = heightAt(camDesired.x, camDesired.z, t);
  if (camDesired.y < camH + 0.85) camDesired.y = camH + 0.85;

  look.copy(ride.position).addScaledVector(fwd, 0.15).addScaledVector(ride.normal, 0.95);

  if (!ready) {
    camera.position.copy(camDesired);
    lookSmooth.copy(look);
    ready = true;
  } else {
    const k = 1 - Math.exp(-2.6 * dt);
    camera.position.lerp(camDesired, k);
    lookSmooth.lerp(look, 1 - Math.exp(-4 * dt));
  }
  camera.up.copy(ride.normal);
  camera.lookAt(lookSmooth);
  camera.rotateZ(-ride.bank * 0.1);

  sunPos.copy(focus).addScaledVector(SUN, 40);
  sun.position.copy(sunPos);
  sun.target.position.copy(focus);
  fillPos.copy(focus).addScaledVector(fwd, -6).addScaledVector(right, -10).setY(focus.y + 4);
  fill.position.copy(fillPos);
  fill.target?.position?.copy?.(focus);

  sky.position.copy(camera.position);
  water.uniforms.uTime.value = t;

  const tile = water.tile;
  water.mesh.position.x = Math.floor(ride.position.x / tile) * tile;
  water.mesh.position.z = Math.floor(ride.position.z / tile) * tile;

  rig.tailMark.getWorldPosition(tailWorld);
  const tp = new THREE.Vector2(tailWorld.x, tailWorld.z);
  if (!trailWarm) {
    for (const p of trail) p.copy(tp);
    lastTrail.copy(tp);
    trailWarm = true;
  } else if (tp.distanceTo(lastTrail) > 0.5) {
    for (let i = TRAIL_N - 1; i > 0; i--) trail[i].copy(trail[i - 1]);
    trail[0].copy(tp);
    lastTrail.copy(tp);
  }

  updateSpray(dt, t);
  updateFlock(t);
  clouds.position.set(ride.position.x, 0, ride.position.z);

  publishTest(t);
}

const _beak = new THREE.Vector3();
const _head = new THREE.Vector3();
const _nose = new THREE.Vector3();
const _tail = new THREE.Vector3();
const _axis = new THREE.Vector3();

function publishTest(t) {
  if (t < 0.4) return;
  rig.beakTip.getWorldPosition(_beak);
  rig.head.getWorldPosition(_head);
  rig.nose.getWorldPosition(_nose);
  rig.tailMark.getWorldPosition(_tail);
  const beakFwd = _beak.sub(_head);
  beakFwd.y = 0;
  beakFwd.normalize();
  const boardFwd = _nose.sub(_tail);
  boardFwd.y = 0;
  boardFwd.normalize();
  _axis.set(0, 1, 0).applyQuaternion(rig.root.quaternion);
  const toCam = camera.position.clone().sub(rig.root.position);
  toCam.y = 0;
  toCam.normalize();
  const waterThere = heightAt(camera.position.x, camera.position.z, t);
  document.body.dataset.facing = beakFwd.dot(ride.travel).toFixed(3);
  document.body.dataset.board = boardFwd.dot(ride.travel).toFixed(3);
  document.body.dataset.up = _axis.dot(ride.normal).toFixed(3);
  document.body.dataset.cam = toCam.dot(ride.travel).toFixed(3);
  document.body.dataset.above = (camera.position.y - waterThere).toFixed(2);
  document.body.dataset.moved = rig.root.position.length().toFixed(2);
}

function createSpray() {
  const n = 180;
  const positions = new Float32Array(n * 3);
  const ages = new Float32Array(n);
  const vels = new Float32Array(n * 3);
  ages.fill(0);
  const geo = new THREE.BufferGeometry();
  geo.setAttribute("position", new THREE.BufferAttribute(positions, 3));
  const mat = new THREE.PointsMaterial({
    color: 0xfff8f2,
    size: 0.22,
    map: sprayTexture(),
    transparent: true,
    depthWrite: false,
    opacity: 0.85,
    sizeAttenuation: true,
  });
  const points = new THREE.Points(geo, mat);
  points.frustumCulled = false;
  return { points, positions, ages, vels, n, cursor: 0 };
}

function updateSpray(dt, t) {
  const { positions, ages, vels, n } = spray;
  const energy = 0.45 + (1 - ride.lip) * 0.7 + ride.lip * ride.lip * 0.9;
  const births = Math.min(8, energy * dt * 70);
  for (let k = 0; k < births; k++) {
    const i = spray.cursor;
    spray.cursor = (spray.cursor + 1) % n;
    const fromTail = Math.random() < 0.65;
    if (fromTail) emitA.set(0.05 * (Math.random() - 0.5), 0.08, 1.05);
    else emitA.set(0.28, 0.06, 0.15);
    rig.root.localToWorld(emitA);
    const j = i * 3;
    positions[j] = emitA.x;
    positions[j + 1] = emitA.y;
    positions[j + 2] = emitA.z;
    const back = -1;
    vels[j] = -ride.travel.x * (1.4 + Math.random() * 2.2) + (Math.random() - 0.5) * 0.8;
    vels[j + 1] = 1.1 + Math.random() * 2.4 + ride.lip * 1.6;
    vels[j + 2] = -ride.travel.z * (1.4 + Math.random() * 2.2) + right.x * 0 + (Math.random() - 0.3) * 1.1;
    // Throw spray downhill, toward the trough (flat right).
    vels[j] += right.x * (0.4 + Math.random() * 1.3);
    vels[j + 2] += right.z * (0.4 + Math.random() * 1.3);
    ages[i] = 0.35 + Math.random() * 0.45;
    void back;
    void t;
  }
  for (let i = 0; i < n; i++) {
    const j = i * 3;
    if (ages[i] <= 0) {
      positions[j + 1] = -999;
      continue;
    }
    ages[i] -= dt;
    vels[j + 1] -= 5.2 * dt;
    positions[j] += vels[j] * dt;
    positions[j + 1] += vels[j + 1] * dt;
    positions[j + 2] += vels[j + 2] * dt;
  }
  spray.points.geometry.attributes.position.needsUpdate = true;
}

function createFlock() {
  const group = new THREE.Group();
  const birds = [];
  const bodyMat = new THREE.MeshStandardMaterial({ color: 0x2e3438, roughness: 0.6 });
  for (let i = 0; i < 4; i++) {
    const b = new THREE.Group();
    const wingGeo = new THREE.BoxGeometry(0.42, 0.02, 0.12);
    const left = new THREE.Mesh(wingGeo, bodyMat);
    const rightW = new THREE.Mesh(wingGeo, bodyMat);
    left.position.x = -0.24;
    rightW.position.x = 0.24;
    b.add(left, rightW);
    group.add(b);
    birds.push({ group: b, left, right: rightW, phase: i * 1.7, radius: 7 + i * 1.4, alt: 5.2 + i * 0.7 });
  }
  return { group, birds };
}

function updateFlock(t) {
  flock.group.position.set(ride.position.x, 0, ride.position.z);
  for (const b of flock.birds) {
    const a = t * 0.23 + b.phase;
    b.group.position.set(Math.cos(a) * b.radius, b.alt + Math.sin(a * 2) * 0.3, -6 + Math.sin(a) * 3.5);
    const flap = Math.sin(t * 6 + b.phase) * 0.5;
    b.left.rotation.z = 0.4 + flap;
    b.right.rotation.z = -0.4 - flap;
    b.group.rotation.y = -a + Math.PI / 2;
  }
}

function createClouds() {
  const group = new THREE.Group();
  const mat = new THREE.MeshBasicMaterial({
    color: 0xffe3d0,
    transparent: true,
    opacity: 0.78,
    depthWrite: false,
  });
  const geo = new THREE.SphereGeometry(1, 16, 12);
  const spots = [
    [-18, 11, -14, 3.2],
    [-8, 13, -22, 4.1],
    [16, 12, -16, 3.4],
    [6, 15, -28, 5],
    [-24, 14, -8, 2.6],
    [22, 16, -26, 3.8],
  ];
  for (const [x, y, z, s] of spots) {
    const puff = new THREE.Group();
    puff.position.set(x, y, z);
    for (let i = 0; i < 4; i++) {
      const m = new THREE.Mesh(geo, mat);
      m.position.set((i - 1.5) * s * 0.45, (i % 2) * 0.4, i * 0.15);
      m.scale.setScalar(s * (0.7 + (i % 3) * 0.12));
      puff.add(m);
    }
    group.add(puff);
  }
  return group;
}

function tick() {
  const dt = Math.min(clock.getDelta(), 0.05);
  const t = clock.elapsedTime;
  frame(t, dt);
  renderer.render(scene, camera);
  requestAnimationFrame(tick);
}

frame(0, 1 / 60);
renderer.render(scene, camera);
requestAnimationFrame(tick);

