  rig.wingL.rotation.set(0.12, 0.55, -0.48 - flap - open + ride.bank * 0.2);

  rig.head.rotation.x = -0.06 + Math.sin(t * 1.6) * 0.035 - ride.pitch * 0.25;
  rig.head.rotation.z = -ride.bank * 0.3;
  rig.head.rotation.y = Math.sin(t * 0.8) * 0.04;

