import * as THREE from 'three';
import { heightAt, wavePhase, WAVES } from './ocean.js';
import { rideXZ, ridePhase, sampleRide, alignToSurface, createRideState } from './ride.js';

const TAU = Math.PI * 2;
function sinPhase(i, x, z, t) { return Math.sin(wavePhase(i, x, z, t)); }

let worst = 0;
for (const t of [0, 0.4, 1, 3.14, 8, 20, 100, 5000]) {
  const { x, z, phase } = rideXZ(t);
  const got = Math.sin(wavePhase(0, x, z, t));
  const want = Math.sin(phase);
  const err = Math.abs(got - want);
  worst = Math.max(worst, err);
  const h = heightAt(x, z, t);
  const crestZ = ((Math.PI/2) + WAVES.w[0]*t) / WAVES.k[0];
  const hCrest = heightAt(x, crestZ, t);
  if (!(z > crestZ)) console.log('FAIL crest side', t, z, crestZ);
  if (!(h < hCrest + 0.02)) console.log('FAIL height vs crest', t, h, hCrest);
  if (err > 1e-6) console.log('FAIL phase', t, err, got, want);
}
console.log('worst phase sin err', worst);

const obj = new THREE.Object3D();
const normal = new THREE.Vector3(-0.2, 1, 0.35).normalize();
const travel = new THREE.Vector3(1, 0, 0.25).normalize();
alignToSurface(obj, normal, travel);
const yAxis = new THREE.Vector3(0,1,0).applyQuaternion(obj.quaternion);
const fwd = new THREE.Vector3(0,0,-1).applyQuaternion(obj.quaternion);
const xAxis = new THREE.Vector3(1,0,0).applyQuaternion(obj.quaternion);
console.log('up dot', yAxis.dot(normal).toFixed(4));
console.log('fwd·normal', fwd.dot(normal).toFixed(4));
console.log('fwd·travel', fwd.dot(travel).toFixed(4));
console.log('right handed', xAxis.clone().cross(yAxis).dot(new THREE.Vector3(0,0,-1).applyQuaternion(obj.quaternion)).toFixed(4));
if (yAxis.dot(normal) < 0.999) console.log('FAIL up');
if (Math.abs(fwd.dot(normal)) > 1e-3) console.log('FAIL tangent');
if (fwd.dot(travel) < 0.9) console.log('FAIL facing');

const ride = createRideState();
for (const t of [0, 1.2, 4, 9]) {
  sampleRide(t, ride);
  alignToSurface(obj, ride.normal, ride.travel);
  const f = new THREE.Vector3(0,0,-1).applyQuaternion(obj.quaternion);
  const u = new THREE.Vector3(0,1,0).applyQuaternion(obj.quaternion);
  console.log('t', t.toFixed(2), 'face', f.dot(ride.travel).toFixed(3), 'up', u.dot(ride.normal).toFixed(3), 'pos', ride.position.toArray().map(n=>n.toFixed(2)).join(','));
}

// continuity of height
let jump = 0;
let prev = heightAt(0,0,0);
for (let i = 1; i < 200; i++) {
  const h = heightAt(i*0.25, i*0.1, i*0.05);
  jump = Math.max(jump, Math.abs(h-prev));
  prev = h;
}
console.log('max step', jump.toFixed(3));
"

