  pos.y = h;
  vec4 world = modelMatrix * vec4(pos, 1.0);
  vWorld = world.xyz;
  vNormal = normalize(mat3(modelMatrix) * n);
  vHeight = h;
  vFoam = clamp(lip * 0.9 + wake * 0.8, 0.0, 1.0);
  gl_Position = projectionMatrix * viewMatrix * world;
}
